const row = $json;
const old = row.old_lead ?? {};
const allMessages = Array.isArray(row.messages) ? row.messages : [];
const pageId = String(row.page_id || '');
const isTechaz = (pageId === '1274733055725344');

// 1. Regex bóc tách SĐT & Email
const allText = allMessages.map(m => m.text ?? "").join("\n");
const emailMatch = allText.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
const phoneMatches = allText.match(/(?:\+84|84|0)(?:[\s.\-]?\d){8,10}/g) ?? [];
function norm(v) {
  if (!v) return null;
  let p = v.replace(/[^\d+]/g, "");
  if (p.startsWith("+84")) p = "0" + p.slice(3);
  else if (p.startsWith("84")) p = "0" + p.slice(2);
  return p;
}
const regexPhone = phoneMatches.length ? norm(phoneMatches[0]) : null;
const regexEmail = emailMatch ? emailMatch[0].toLowerCase() : null;

// 2. Cắt gọn thông minh 40 tin nhắn gần nhất
const recentMessages = allMessages.slice(-40);
let conversation = recentMessages.map((m, i) => `${i + 1}. [${m.sender ?? "KHÁCH"}]: ${m.text ?? ""}`).join("\n");
if (conversation.length > 8000) {
  conversation = "...(lược bớt hội thoại cũ)...\n" + conversation.slice(-8000);
}

let prompt = "";

if (isTechaz) {
  // --- PAGE TECHAZ: CHỈ CÓ DUY NHẤT 1 SẢN PHẨM LÀ CMS INTELLICAD ---
  prompt = `Bạn là chuyên gia thẩm định & trích xuất khách hàng tiềm năng cho phần mềm bản quyền CMS IntelliCAD (Công ty Cổ phần Techaz).
Nhiệm vụ: Phân tích kỹ hội thoại Facebook Messenger để trích xuất đầy đủ thông tin khách hàng và nhu cầu/mong muốn thực tế của họ về CMS IntelliCAD.

TIÊU CHÍ PHÂN TÍCH:
- Sản phẩm luôn là: CMS IntelliCAD (các phiên bản: PE, PE Plus, Pro).
- Nhu cầu (need): Khách muốn dùng thử (trial), hỏi giá bản quyền vĩnh viễn/thuê bao, xin báo giá bao nhiêu license, hỏi so sánh AutoCAD, hay gặp lỗi cài đặt.
- Yêu cầu báo giá (request_quote): true nếu khách hỏi giá, xin báo giá, hỏi chi phí mua, cung cấp MST xuất hóa đơn; false nếu chỉ dùng thử/hỏi kỹ thuật.
- Điểm Lead: HOT (80-100, có SĐT/Email rõ ràng, cần báo giá gấp), WARM (50-79, tìm hiểu tính năng, chưa có SĐT), COLD (1-49, spam, chào hàng).

DỮ LIỆU CŨ HIỆN CÓ:
- Tên: ${old.full_name ?? "null"} | SĐT: ${old.phone ?? "null"} | Email: ${old.email ?? "null"} | Công ty: ${old.company ?? "null"}
- SĐT trích xuất regex: ${regexPhone ?? "null"} | Email: ${regexEmail ?? "null"}

HỘI THOẠI KHÁCH HÀNG (SẢN PHẨM: CMS IntelliCAD):
${conversation || "(Không có nội dung)"}

ĐỊNH DẠNG JSON BẮT BUỘC (DUY NHẤT JSON HỢP LỆ):
{
  "product_name": "CMS IntelliCAD",
  "product_code": "CMS_INTELLICAD",
  "customer_name": "Tên khách hoặc null",
  "phone": "Số điện thoại hoặc null",
  "email": "Email hoặc null",
  "company": "Tên công ty hoặc null",
  "customer_type": "Cá nhân | Doanh nghiệp | Chưa xác định",
  "quantity": 1,
  "need": "Mô tả chi tiết nhu cầu",
  "request_quote": true,
  "intent": "Báo giá & Mua bản quyền | Dùng thử phần mềm | Tư vấn kỹ thuật | Tìm hiểu thông tin",
  "lead_score": 85,
  "lead_tier": "HOT | WARM | COLD",
  "lead_summary": "Tóm tắt ngắn gọn 1 câu",
  "confidence": 0.95
}`;
} else {
  // --- PAGE CIC: ĐA DẠNG NHIỀU SẢN PHẨM & GIẢI PHÁP ---
  prompt = `Bạn là chuyên gia thẩm định & trích xuất khách hàng tiềm năng cao cấp của Công ty Cổ phần Công nghệ và Tư vấn CIC (CIC JSC).

BỐI CẢNH DOANH NGHIỆP:
- Page Facebook: "CIC Technology and Consultancy JSC"
- Công ty CIC cung cấp ĐA DẠNG CÁC SẢN PHẨM & GIẢI PHÁP KỸ THUẬT:
  1. Phần mềm CAD: "enjiCAD" (CAD bản quyền thay thế AutoCAD)
  2. Robot & Thiết bị Xây dựng: "Robot Xây dựng" (Robot gạt phẳng, xoa nền, xoa mịn bê tông; Robot kiểm tra trạm biến áp,...)
  3. Phần mềm Kết cấu CSi: "ETABS", "SAP2000", "SAFE", "CSiBridge", "PERFORM-3D"
  4. Phần mềm Địa kỹ thuật: "PLAXIS 2D", "PLAXIS 3D", "GEO5", "GeoStudio"
  5. Phần mềm Xây dựng & Dự toán: "Escon 15", "RDW", "VinaSAS", "stCAD", "IDEA StatiCa"
  6. Thiết bị thí nghiệm & đo đạc: Máy quét 3D Laser, Radar xuyên đất (GPR), Thiết bị kiểm tra kết cấu bê tông, NDT
  7. Giao thông & Môi trường: "PTV VISSIM", "PTV VISUM", "CadnaA", "OILMAP"

QUY TẮC BÓC TÁCH CỰC KỲ CẨN THẬN:
- "product_name": Đọc kỹ toàn bộ tin nhắn, câu hỏi, và form đăng ký để xác định CHÍNH XÁC tên sản phẩm/giải pháp khách hàng đang quan tâm hoặc xin báo giá.
  * Tuyệt đối KHÔNG tự ý mặc định là "enjiCAD" nếu khách hỏi về Robot, Kết cấu hoặc thiết bị khác!
  * Ví dụ khách hỏi về Robot xoa nền/gạt phẳng -> ghi: "Robot Xây dựng" hoặc tên cụ thể.
  * Nếu khách hỏi phần mềm CAD -> ghi: "enjiCAD".
  * Nếu khách hỏi phần mềm khác -> ghi đúng tên: "ETABS", "PLAXIS 2D", "GEO5", "Escon 15",...
- "product_code": "ROBOT_XAY_DUNG" | "ENJICAD" | "PLAXIS_2D" | "ETABS" | "GEO5" | "ESCON" | "OTHER".
- "customer_name": Họ và tên khách hàng (chuẩn hóa tên người thật, ví dụ: "Đinh Thuật Chống Thấm", "Quân Đinh").
- "phone": Số điện thoại (chuẩn hóa dạng 0xxxxxxxxx).
- "email": Email liên hệ (chữ thường).
- "company": Tên công ty / doanh nghiệp / nhà thầu (ví dụ: "T&T", "CTY Kiến Nam").
- "customer_type": "Doanh nghiệp" (nếu có công ty, nhà thầu, MST) | "Cá nhân" | "Chưa xác định".
- "quantity": Số lượng cần mua / báo giá (mặc định 1 nếu không nói rõ).
- "need": Chi tiết cụ thể nhu cầu và mong muốn của khách.
- "request_quote": true (nếu khách hỏi giá, xin báo giá, hỏi mua) | false (chỉ hỏi dạo/tìm hiểu).
- "lead_score": 1 - 100.
- "lead_tier": HOT (80-100) | WARM (50-79) | COLD (1-49).
- "lead_summary": 1 câu tóm tắt chính xác.

DỮ LIỆU CŨ HIỆN CÓ:
- Tên: ${old.full_name ?? "null"} | SĐT: ${old.phone ?? "null"} | Email: ${old.email ?? "null"} | Công ty: ${old.company ?? "null"}
- SĐT trích xuất regex: ${regexPhone ?? "null"} | Email: ${regexEmail ?? "null"}

HỘI THOẠI KHÁCH HÀNG:
${conversation || "(Không có nội dung)"}

ĐỊNH DẠNG JSON BẮT BUỘC (DUY NHẤT JSON HỢP LỆ):
{
  "product_name": "Tên sản phẩm cụ thể khách quan tâm",
  "product_code": "Mã sản phẩm",
  "customer_name": "Tên khách hoặc null",
  "phone": "Số điện thoại hoặc null",
  "email": "Email hoặc null",
  "company": "Tên công ty hoặc null",
  "customer_type": "Doanh nghiệp | Cá nhân | Chưa xác định",
  "quantity": 1,
  "need": "Mô tả chi tiết nhu cầu",
  "request_quote": true,
  "intent": "Báo giá & Mua sản phẩm | Dùng thử phần mềm | Tư vấn kỹ thuật | Tìm hiểu giải pháp",
  "lead_score": 85,
  "lead_tier": "HOT | WARM | COLD",
  "lead_summary": "Tóm tắt ngắn gọn 1 câu",
  "confidence": 0.95
}`;
}

return {
  json: {
    conversation_id: row.conversation_id,
    external_user_id: row.external_user_id,
    channel_account_id: row.channel_account_id,
    platform: row.platform,
    page_id: row.page_id,
    page_name: row.page_name,
    conversation_link: row.conversation_link,
    last_message_at: row.last_message_at,
    old_lead: old,
    all_text: allText,
    fb_customer_name: row.fb_customer_name || "",
    regex_phone: regexPhone,
    regex_email: regexEmail,
    ai_payload: {
      model: "qwen3-vl-30b",
      messages: [
        { "role": "system", "content": "Bạn là chuyên gia thẩm định Lead bán hàng B2B. Luôn trả lời bằng định dạng JSON thuần túy, không giải thích." },
        { "role": "user", "content": prompt }
      ],
      temperature: 0.1,
      max_tokens: 1000
    }
  }
};

const response = $json;
const source = $('Build AI Request').item.json;
const old = source.old_lead ?? {};

let rawContent = response.choices?.[0]?.message?.content ?? "";
let cleanJson = rawContent.trim();
if (cleanJson.startsWith("```")) {
  cleanJson = cleanJson.replace(/^```(?:json)?\s*/i, "").replace(/```\s*$/, "").trim();
}

let ai = {};
try {
  ai = JSON.parse(cleanJson);
} catch (e) {
  ai = {
    product_name: null,
    product_code: null,
    customer_name: null,
    phone: source.regex_phone,
    email: source.regex_email,
    company: null,
    customer_type: "Chưa xác định",
    quantity: null,
    need: null,
    request_quote: false,
    intent: "Tìm hiểu thông tin",
    lead_score: (source.regex_phone ? 75 : 40),
    lead_tier: (source.regex_phone ? "HOT" : "WARM"),
    lead_summary: "Trích xuất tự động qua Regex",
    confidence: 0.0
  };
}

// BỘ GIẢI MÃ SẢN PHẨM CHÍNH XÁC THEO PAGE (PRODUCT RESOLVER)
function resolveProduct(pageId, aiProductName, aiProductCode, textContent) {
  if (String(pageId) === '1274733055725344') {
    // Techaz page -> 100% CMS IntelliCAD
    return { id: 1369, name: 'CMS IntelliCAD' };
  }

  // CIC Page (192074964188183)
  const combined = ((aiProductName || '') + ' ' + (aiProductCode || '') + ' ' + (textContent || '')).toLowerCase();

  if (combined.includes('robot') || combined.includes('xoa nền') || combined.includes('gạt phẳng') || combined.includes('xoa mịn') || combined.includes('bê tông')) {
    return { id: 1363, name: 'Robot Xây dựng' };
  }
  if (combined.includes('enjicad') || combined.includes('enji cad') || combined.includes('cad thay thế')) {
    return { id: 1103, name: 'enjiCAD' };
  }
  if (combined.includes('plaxis')) {
    if (combined.includes('3d')) return { id: 1128, name: 'PLAXIS 3D' };
    return { id: 1127, name: 'PLAXIS 2D' };
  }
  if (combined.includes('etabs')) {
    return { id: 1110, name: 'ETABS' };
  }
  if (combined.includes('sap2000') || combined.includes('sap 2000')) {
    return { id: 1109, name: 'SAP2000' };
  }
  if (combined.includes('geo5')) {
    return { id: 1214, name: 'GEO5' };
  }
  if (combined.includes('geostudio')) {
    return { id: 1213, name: 'GeoStudio' };
  }
  if (combined.includes('escon')) {
    return { id: 1105, name: 'Escon 15' };
  }
  if (combined.includes('safe')) {
    return { id: 1111, name: 'SAFE' };
  }
  if (combined.includes('csibridge')) {
    return { id: 1113, name: 'CSiBridge' };
  }
  if (combined.includes('vissim')) {
    return { id: 1147, name: 'PTV VISSIM' };
  }
  if (combined.includes('visum')) {
    return { id: 1146, name: 'PTV VISUM' };
  }
  if (combined.includes('cadnaa')) {
    return { id: 1173, name: 'CadnaA' };
  }
  if (combined.includes('radar') || combined.includes('georadar') || combined.includes('gpr')) {
    return { id: 1207, name: 'Radar xuyên đất (GPR/GEORADAR)' };
  }
  if (combined.includes('conquest')) {
    return { id: 1259, name: 'Thiết bị scan bê tông bằng radar CONQUEST 100' };
  }
  if (aiProductName && aiProductName !== 'null' && aiProductName.trim()) {
    return { id: 1103, name: aiProductName.trim() };
  }
  return { id: 1103, name: 'enjiCAD' };
}

const resolvedProd = resolveProduct(source.page_id, ai.product_name, ai.product_code, source.all_text);
const productId = resolvedProd.id;
const productName = resolvedProd.name;

const pref = (n, o) => (n === null || n === undefined || n === "") ? (o ?? null) : n;
const customerName = pref(ai.customer_name, old.full_name) || source.fb_customer_name || "Khách Facebook";
const phone = pref(ai.phone ?? source.regex_phone, old.phone);
const email = pref(ai.email ?? source.regex_email, old.email);
const company = pref(ai.company, old.company);
const quantity = pref(ai.quantity, old.requested_quantity);
const need = pref(ai.need, old.need) || ("Tư vấn giải pháp " + productName);

let customerType = ["Cá nhân", "Doanh nghiệp"].includes(ai.customer_type) ? ai.customer_type : (old.customer_type === "personal" ? "Cá nhân" : (old.customer_type === "business" ? "Doanh nghiệp" : "Chưa xác định"));
const requestQuote = Boolean(ai.request_quote || old.quote_status);

let quotationStatus = old.quote_status ?? "CHƯA BÁO GIÁ";
if (quotationStatus === "CHƯA BÁO GIÁ" && requestQuote) {
  quotationStatus = "ĐANG XỬ LÝ";
}

let leadStatus = old.lead_status ?? "new";
if ((phone || email) && need) {
  leadStatus = "qualified";
}

let score = Number(ai.lead_score ?? 50);
if (phone && score < 75) score = 80;
let tier = String(ai.lead_tier || (score >= 80 ? "HOT" : (score >= 50 ? "WARM" : "COLD"))).toUpperCase();
const isHot = tier === "HOT" || score >= 80;

const now = new Date().toISOString();

return {
  json: {
    conversation_id: source.conversation_id,
    external_user_id: source.external_user_id,
    channel_account_id: source.channel_account_id,
    product_id: productId,
    product: productName,
    customer_name: customerName,
    phone: phone,
    email: email,
    company: company,
    customer_type: customerType,
    quantity: quantity,
    need: need,
    intent: ai.intent || (requestQuote ? "Báo giá & Mua sản phẩm" : "Tìm hiểu thông tin"),
    request_quote: requestQuote,
    lead_status: leadStatus,
    quotation_status: quotationStatus,
    quote_code: old.request_code ?? null,
    conversation_link: source.conversation_link,
    last_contact_at: source.last_message_at ?? now,
    lead_score: score,
    lead_tier: tier,
    lead_summary: ai.lead_summary || "",
    is_hot_lead: isHot,
    extraction_confidence: Number(ai.confidence ?? 0.8)
  }
};

const x = $json;
const s = $('Merge + Build Full 21 Fields').item.json;

const tierPrefix = s.lead_tier === 'HOT' ? '🔥 HOT' : (s.lead_tier === 'WARM' ? '⚡ WARM' : '❄️ COLD');
const statusDisplay = `${tierPrefix} (${s.lead_score}/100) - ${(x.status ?? s.lead_status ?? "NEW").toUpperCase()}`;

return {
  json: {
    "Mã báo giá": x.quote_code ?? s.quote_code ?? null,
    "Nguồn lead": "Facebook",
    "Sản phẩm": "CMS IntelliCAD",
    "Tên khách hàng": x.full_name ?? s.customer_name ?? null,
    "Số điện thoại": x.phone ?? s.phone ?? null,
    "Email": x.email ?? s.email ?? null,
    "Công ty": x.company ?? s.company ?? null,
    "Loại khách hàng": s.customer_type ?? "Chưa xác định",
    "Số lượng": x.requested_quantity ?? s.quantity ?? null,
    "Nhu cầu": x.need ?? s.need ?? null,
    "Trạng thái lead": statusDisplay,
    "Trạng thái báo giá": (x.quotation_status ?? s.quotation_status ?? "CHƯA BÁO GIÁ").toUpperCase(),
    "Nhân viên phụ trách": null,
    "Lần liên hệ gần nhất": x.last_contacted_at ?? s.last_contact_at ?? null,
    "Lịch liên hệ tiếp theo": null,
    "Ghi chú nhân viên": s.lead_summary || null,
    "Link hội thoại": s.conversation_link ?? null,
    "Ngày tạo lead": new Date().toISOString(),
    "Cập nhật lần cuối": new Date().toISOString(),
    "Cập nhật DB": new Date().toISOString(),
    "Trạng thái đồng bộ": "PENDING",
    // Trường phụ trợ thông báo
    "is_hot_lead": s.is_hot_lead,
    "lead_score": s.lead_score,
    "lead_tier": s.lead_tier
  }
};

